package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.data.domain.PageImpl; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class RelatorioPessoaApplicationServiceTest { @Mock PessoaRepository pessoas; @Mock OrganizacaoEclesialRepository organizacoes; @Mock SegurancaOrganizacaoService seguranca; @InjectMocks RelatorioPessoaApplicationService service;
 @Test void deveExigirOrganizacao(){assertThrows(IllegalArgumentException.class,()->service.consultar(new RelatorioPessoaFiltro(null,null,null,0,25,"nome","asc")));}
 @Test void deveValidarAcessoOrganizacional(){UUID u=UUID.randomUUID(); var org=new OrganizacaoEclesial(); org.setNome("Paróquia"); when(organizacoes.findByUuid(u)).thenReturn(Optional.of(org)); when(pessoas.pesquisarRelatorio(eq(u),isNull(),isNull(),any())).thenReturn(new PageImpl<>(List.of())); service.consultar(new RelatorioPessoaFiltro(u,null,null,0,25,"nome","asc")); verify(seguranca).validarAcesso(u);}
}
